INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22801, 'Matthew 22:46', 'Matthew', 22, 46, '&nbsp;يو کس هم د هغۀ په جواب څۀ ونۀ وئيل او د دې ورځې نه پس هيچا هم د هغۀ نه د تپوس کولو همت ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22802, 'Matthew 23:1', 'Matthew', 23, 1, '&nbsp;عيسىٰ بيا خپلو مريدانو او خلقو ته داسې خبرې وکړې چې', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22803, 'Matthew 23:2', 'Matthew', 23, 2, '&nbsp;”د شرعې عالمان او فريسيان د موسىٰ په ګدۍ ناست دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22804, 'Matthew 23:3', 'Matthew', 23, 3, '&nbsp;نو هر څۀ چې دوئ تاسو ته وائى هغه کوئ د هغوئ خبرو ته غوږ نيسئ، خو د هغوئ په شان کارونه مۀ کوئ ځکه چې دوئ وائى يو څۀ او کوى بل څۀ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22805, 'Matthew 23:4', 'Matthew', 23, 4, '&nbsp;دوئ مذهبى درانۀ پيټى تړى او د خلقو په اوږو يې باروى خو دا نۀ غواړى چې يو ته د اوچتولو دپاره خپله ګوته هم وروړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22806, 'Matthew 23:5', 'Matthew', 23, 5, '&nbsp;دوئ چې هر څۀ کوى دا د خلقو د ليدو دپاره کوى. هغوئ خپل تعويذونه غټ جوړوى او د خپلو چوغو زونډى لويوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22807, 'Matthew 23:6', 'Matthew', 23, 6, '&nbsp;دوئ په دعوت کښې خاص ځايونه خوښوى او په عبادتخانو کښې د مشرۍ کُرسۍ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22808, 'Matthew 23:7', 'Matthew', 23, 7, '&nbsp;او په بازارونو کښې د عزت په سلامونو ډېر خوشحاليږى چې د اُستاذ په نامه ياد شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22809, 'Matthew 23:8', 'Matthew', 23, 8, '&nbsp;خو تاسو ته دې څوک اُستاذ ونۀ وائى ځکه چې ستاسو خو يو اُستاذ شته او تاسو ټول وروڼه يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22810, 'Matthew 23:9', 'Matthew', 23, 9, '&nbsp;په دې دُنيا کښې هيچا ته پلار مۀ وايئ ځکه چې ستاسو خو يو پلار شته او هغه په آسمان کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22811, 'Matthew 23:10', 'Matthew', 23, 10, '&nbsp;او تاسو ته دې څوک اُستاذ ونۀ وائې ځکه چې ستاسو يو اُستاذ شته او هغه مسيح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22812, 'Matthew 23:11', 'Matthew', 23, 11, '&nbsp;په تاسو کښې دې د ټولو نه لوئ ستاسو خادِم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22813, 'Matthew 23:12', 'Matthew', 23, 12, '&nbsp;او هر هغه څوک چې ځان اوچتوى، هغه به عاجز کړے شى او هر هغه څوک چې ځان عاجز کړى، هغه به اوچت کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22814, 'Matthew 23:15', 'Matthew', 23, 15, '&nbsp;اے د شرعې عالمانو، فريسيانو، مُنافقانو، ځکه چې تاسو په زمکه او سمندر سفر کوئ د دې دپاره چې يو کس خپل دين ته راواړوئ او کله چې هغه راواړوئ نو تاسو هغه د خپل ځان نه دوه چنده دوزخى جوړ کړئ لکه څنګه چې تاسو يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22815, 'Matthew 23:16', 'Matthew', 23, 16, '&nbsp;اے ړندو لارښودونکو، په تاسو دې افسوس وى، ځکه چې تاسو وايئ چې کۀ څوک د خُدائ په کور قسم وخورى نو دا څۀ خبره نۀ ده، خو کۀ چرته يو کس د هغۀ په سرو زرو قسم وخورى، نو هغه د خپل قسم پابند دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22816, 'Matthew 23:17', 'Matthew', 23, 17, '&nbsp;اے ړندو کم عقلو، په دې دواړو کښې کوم څيز اهم دے، سرۀ زر او کۀ د خُدائ کور چې سرۀ زر هم پاکوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22817, 'Matthew 23:18', 'Matthew', 23, 18, '&nbsp;يا تاسو دا وايئ کۀ څوک په قربان‌ګاه قسم وخورى نو هيڅ خبره نۀ ده، خو کۀ څوک د قربان‌ګاه په شکرانې قسم وخورى نو هغه به پابند وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22818, 'Matthew 23:19', 'Matthew', 23, 19, '&nbsp;اے ړندو، کوم څيز زيات اهم دے، شکرانه کۀ هغه قربان‌ګاه چې شکرانه هم پاکوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22819, 'Matthew 23:20', 'Matthew', 23, 20, '&nbsp;نو هرکله چې څوک په قربان‌ګاه قسم خورى نو هغه په قربان‌ګاه او د هغې په شکرانو دواړو قسم خورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22820, 'Matthew 23:21', 'Matthew', 23, 21, '&nbsp;څوک چې د خُدائ په کور قسم خورى، نو هغه په هغۀ او څوک چې هلته اوسى، په دواړو قسم خورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22821, 'Matthew 23:22', 'Matthew', 23, 22, '&nbsp;او څوک چې په آسمان قسم خورى نو دا داسې دى لکه چې هغه د خُدائ پاک په تخت او د خُدائ په ذات باندې قسم خورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22822, 'Matthew 23:23', 'Matthew', 23, 23, '&nbsp;اے د شرعې عالمانو، فريسيانو، مُنافقانو، په تاسو افسوس چې تاسو خو د پودينې د کاږو او د زېرې لسمه حِصه ورکوئ خو د شريعت معتبرې خبرې لکه اِنصاف، رحم او وفادارى مو پرېښې ده. په اصل کښې په کار دا وُو چې تاسو په دې هم عمل کولے او هغه مو هم نۀ پرېښودلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22823, 'Matthew 23:24', 'Matthew', 23, 24, '&nbsp;اے ړندو لارښودونکو، تاسو خو اوبۀ د ماشى دپاره چاڼ کوئ خو اوښ لواړ تېروئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22824, 'Matthew 23:25', 'Matthew', 23, 25, '&nbsp;اے د شرعې عالمانو، فريسيانو، مُنافقانو، په تاسو افسوس. تاسو خو د کنډول او رکېبۍ بهر مخ وينځئ خو دننه مو هغه د لوټ او د خود غرضۍ د مال نه ډک کړى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22825, 'Matthew 23:26', 'Matthew', 23, 26, '&nbsp;اے ړندو فريسيانو، اول د دننه نه کنډول او رکېبۍ وينځئ، نو بهر نه به هم وينځلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22826, 'Matthew 23:27', 'Matthew', 23, 27, '&nbsp;اے د شرعې عالمانو، فريسيانو، مُنافقانو، په تاسو افسوس. ستاسو مِثال د هغه قبرونو دے چې بهر سپين کړى او ښائسته ښکارى خو دننه د مړو د هډوکو او د نورې ګندګۍ نه ډک وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22827, 'Matthew 23:28', 'Matthew', 23, 28, '&nbsp;دغه حال ستاسو هم دے، په ظاهره خو تاسو صادقان ښکارئ، خو د دننه د منافقت او بې‌شرعې کارونو نه ډک يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22828, 'Matthew 23:29', 'Matthew', 23, 29, '&nbsp;اے د شرعې عالمانو، فريسيانو، مُنافقانو، په تاسو افسوس چې تاسو د نبيانو زيارتونه جوړَوئ او د صادقانو قبرونه سينګاروئ', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22829, 'Matthew 23:30', 'Matthew', 23, 30, '&nbsp;او دا وايئ چې کۀ چرې مونږ د خپل پلار نيکۀ په زمانه کښې ژوندى وے نو د نبيانو په قتلولو کښې به شريک شوى نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22830, 'Matthew 23:31', 'Matthew', 23, 31, '&nbsp;دغسې تاسو په ځان ګواهى کوئ چې تاسو د هغو خلقو زامن يئ چا چې نبيان وژلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22831, 'Matthew 23:32', 'Matthew', 23, 32, '&nbsp;نو ځئ او د خپل پلار نيکۀ نيمګړے کنډول ډک کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22832, 'Matthew 23:33', 'Matthew', 23, 33, '&nbsp;اے مارانو او د مارانو بچو، تاسو به د دوزخ د سزا نه څنګه خلاص شئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22833, 'Matthew 23:34', 'Matthew', 23, 34, '&nbsp;ځکه زۀ تاسو ته نبيان، هوښياران او د خُدائ پاک د لارې عالمان درلېږم نو په تاسو کښې به ځينى مړۀ کړى، ځينې به په سولۍ کړى او ځينې به په خپلو عبادتخانو کښې په کوړو ووهى او د يو ښار نه به يې بل ښار ته وشړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22834, 'Matthew 23:35', 'Matthew', 23, 35, '&nbsp;دغه شان به په زمکه د ټولو صادقانو د توئ شوې وينې ذمه وارى ستاسو په غاړه وى، د بې‌ګناه هابيل نه د برکياه د زوئ زکرياه تر وينې پورې، څوک چې تاسو د خُدائ د کور او قربان‌ګاه په مينځ کښې مړ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22835, 'Matthew 23:36', 'Matthew', 23, 36, '&nbsp;زۀ تاسو ته رښتيا وايم، چې دې پيړۍ ته به د دې ټولو سزا ملاويږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22836, 'Matthew 23:37', 'Matthew', 23, 37, '&nbsp;اے يروشلمه، اے د يروشلم ښاريې چې تۀ نبيان وژنې او رسولان سنګساروې کوم چې تا ته رالېږلے شوى دى. ما څو ځله دا ارمان وکړو چې ستا بچى راغونډ کړم، داسې لکه چې چرګه خپل بچى د وزرو لاندې راغونډوى، خو تا دا نۀ غوښتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22837, 'Matthew 23:38', 'Matthew', 23, 38, '&nbsp;او اوس وګوره، هغه دے ستاسو کور خوشے او شاړ پاتې کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22838, 'Matthew 23:39', 'Matthew', 23, 39, '&nbsp;خو بې‌شکه زۀ تاسو ته دا وايم چې تاسو به تر هغه وخته ما ونۀ وينئ ترڅو چې دا ونۀ وايئ چې، مبارک دے هغه څوک چې د مالِک خُدائ په نوم راځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22839, 'Matthew 24:1', 'Matthew', 24, 1, '&nbsp;عيسىٰ د خُدائ د کور نه په وتو وو چې مريدان يې ورنزدې شُو او د خُدائ د کور عمارت يې ورته په ګوته کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22840, 'Matthew 24:2', 'Matthew', 24, 2, '&nbsp;هغۀ ورته وفرمائيل چې، ”دې ټولو آبادو ته وګورئ، زۀ تاسو ته رښتيا وايم چې دلته به يو کاڼے هم د بل دپاسه پاتې نۀ شى او ټول به ونړولے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22841, 'Matthew 24:3', 'Matthew', 24, 3, '&nbsp;څۀ وخت چې عيسىٰ د زيتُونو په غرۀ ناست وو نو مريدان يې ورغلل چې د هغۀ سره په پرده کښې خبرې وکړى. هغوئ ووئيل، ”مونږ ته دا وښايه چې دا هر څۀ به کله وشى او ستا د راتلو او د قيامت د ورځې نښه به څۀ وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22842, 'Matthew 24:4', 'Matthew', 24, 4, '&nbsp;عيسىٰ جواب ورکړو، ”پام کوئ چې څوک مو بې‌لارې نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22843, 'Matthew 24:5', 'Matthew', 24, 5, '&nbsp;ځکه چې ډېر به زما په نوم راشى او دعوىٰ به کوى چې زۀ مسيح يم، او ډېر خلق به بې‌لارې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22844, 'Matthew 24:6', 'Matthew', 24, 6, '&nbsp;داسې وخت به راشى چې تاسو به په خپل خواوشا کښې د جنګونو چغې او سورې او د جنګونو خبر به اورئ، خو ګورئ تاسو مۀ وار خطا کېږئ ځکه چې داسې څيزونه به ضرور پېښيږى خو آخر وخت به لا نۀ وى راغلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22845, 'Matthew 24:7', 'Matthew', 24, 7, '&nbsp;قومونه به د قومونو سره په جنګ وى، بادشاهۍ به د بادشاهۍ سره، په ډېرو ځايونو کښې به زلزلې او قحطونه راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22846, 'Matthew 24:8', 'Matthew', 24, 8, '&nbsp;خو دا ټولې خبرې به لکه د لنګون د دردونو د شروع کېدو په شان وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22847, 'Matthew 24:9', 'Matthew', 24, 9, '&nbsp;تاسو به بيا د تنګسيا او د مرګ دپاره حواله شئ او ټول قومونه به زما د نوم په سبب تاسو سره کينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22848, 'Matthew 24:10', 'Matthew', 24, 10, '&nbsp;په دغه وخت کښې به ډېر تيندک وخورى او د يو بل مُخبرى به کوى او د يو بل سره به کينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22849, 'Matthew 24:11', 'Matthew', 24, 11, '&nbsp;ډېر دروغژن نبيان به راپورته شى او ډېر خلق به بې‌لارې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22850, 'Matthew 24:12', 'Matthew', 24, 12, '&nbsp;او چې بې‌شرعې کارونه زيات شى نو د خلقو به د يو بل سره مينه ختمه شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22851, 'Matthew 24:13', 'Matthew', 24, 13, '&nbsp;خو هغه څوک چې تر آخره قائم پاتې شى هغه به بچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22852, 'Matthew 24:14', 'Matthew', 24, 14, '&nbsp;او په ټوله دُنيا کښې به د بادشاهۍ زېرے خور شى او د ټولو قومونو دپاره به ګواهى شى او بيا به قيامت وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22853, 'Matthew 24:15', 'Matthew', 24, 15, '&nbsp;يوه ورځ راتلونکى ده هر کله چې تاسو د دانيال د پېشګويۍ په مطابق په مقدس ځائ کښې هغه پليت بُت چې تباهى راولى ولاړ ووينئ، (لوستونکى دې پرې پوهه شى)', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22854, 'Matthew 24:16', 'Matthew', 24, 16, '&nbsp;نو هغه څوک چې په يهوديه کښې دى غرونو ته دې وتښتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22855, 'Matthew 24:17', 'Matthew', 24, 17, '&nbsp;کۀ څوک د چت دپاسه وى هغه دې د سامان اوچتولو دپاره ښکته نۀ راکوزيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22856, 'Matthew 24:18', 'Matthew', 24, 18, '&nbsp;او څوک چې په پټو کښې وى هغه دې د خپلې چُوغې راخستلو دپاره نۀ واپس کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22857, 'Matthew 24:19', 'Matthew', 24, 19, '&nbsp;افسوس دے په هغه ښځو چې په دغه ورځو کښې اُميدوارې وى او په هغوئ چې بچو له سينه ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22858, 'Matthew 24:20', 'Matthew', 24, 20, '&nbsp;دُعا کوئ چې ستاسو تېښته نۀ خو په ژمى کښې او نۀ د سبت په ورځ راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22859, 'Matthew 24:21', 'Matthew', 24, 21, '&nbsp;ځکه چې هغه به د لوئ مصيبت ورځ وى. داسې وخت د دُنيا د شروع نه تر اوسه لا نۀ دے راغلے او نۀ به بيا چرته راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22860, 'Matthew 24:22', 'Matthew', 24, 22, '&nbsp;کۀ هغه د تکليف ورځې لنډې کړے شوې نۀ وې نو هيڅ يو بشر به هم بچ شوے نۀ وے، خو د خُدائ پاک د غوره شوو د خاطره به هغه ورځې لنډې کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22861, 'Matthew 24:23', 'Matthew', 24, 23, '&nbsp;او کۀ بيا تاسو ته په دغه وخت کښې څوک دا ووائى چې وګورئ مسيح دلته دے يا هلته دے، نو باور پرې مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
