(22863, 'Matthew 24:25', 'Matthew', 24, 25, '&nbsp;ګورئ، ما تاسو د دې د کېدو نه مخکښې خبردار کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22864, 'Matthew 24:26', 'Matthew', 24, 26, '&nbsp;کۀ هغوئ تاسو ته ووائى چې هغه هلته په بيابان کښې دے نو هغۀ پسې بهر مۀ ځئ، او کۀ هغوئ ووائى چې هغه دننه په کوټه کښې دے نو باور پرې مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22865, 'Matthew 24:27', 'Matthew', 24, 27, '&nbsp;لکه څنګه چې برېښنا د مشرق نه تر مغرب پورې رسى دغه شان به د اِبن آدم راتلل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22866, 'Matthew 24:28', 'Matthew', 24, 28, '&nbsp;چرته چې مرداره وى هلته به ټپوسان راټوليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22867, 'Matthew 24:29', 'Matthew', 24, 29, '&nbsp;او هر کله چې د دغه ورځو تنګسيا تيره شى نو ”سمدستى به نمر تور شى او د سپوږمۍ رڼا به ورکه شى، ستورى به د آسمان نه راپرېوځى او آسمانى طاقتونه به ولړزولے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22868, 'Matthew 24:30', 'Matthew', 24, 30, '&nbsp;بيا به په آسمان کښې د اِبن آدم د راتلو نښه ښکاره شى، د دُنيا ټول قومونه به ژړا انګولا کوى او هغوئ به اِبن آدم ووينى چې د آسمان په وريځو کښې به د قدرت او د ډيرې لويئ سره راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22869, 'Matthew 24:31', 'Matthew', 24, 31, '&nbsp;او هغه به خپلې فرښتې د بيګل په لوئ آواز سره راولېږى او هغوئ به د څلورو طرفونو نه، يعنې د آسمان د يو سر نه تر بله سره، غوره شوى خلق راټول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22870, 'Matthew 24:32', 'Matthew', 24, 32, '&nbsp;د اينځر د ونې نه سبق واخلئ. هر کله چې د هغې نازکې څانګې غوټۍ ونيسى او پاڼې وکړى نو تاسو پوهه شئ چې اوړے په راتلو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22871, 'Matthew 24:33', 'Matthew', 24, 33, '&nbsp;هم دغه شان چې تاسو دا ټولې نښې ووينئ نو تاسو پوهه شئ چې هغه نزدې دے او په دروازه کښې ولاړ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22872, 'Matthew 24:34', 'Matthew', 24, 34, '&nbsp;زۀ تاسو ته دا وايم چې دا موجوده پيړۍ به تر هغې ختمه نۀ شى ترڅو چې دا ټولې خبرې ونۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22873, 'Matthew 24:35', 'Matthew', 24, 35, '&nbsp;زمکه او آسمان به فنا شى خو زما کلام به هيچرې فنا نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22874, 'Matthew 24:36', 'Matthew', 24, 36, '&nbsp;خو د هغې ورځې او ساعت هيچا ته پته نشته، نۀ خو د آسمان فرښتو ته پته شته او نۀ زوئ ته، خو يو پلار پرې خبر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22875, 'Matthew 24:37', 'Matthew', 24, 37, '&nbsp;لکه څنګه چې د نوح په ورځو کښې وشول نو دغه شان به د اِبن آدم په راتلو هم وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22876, 'Matthew 24:38', 'Matthew', 24, 38, '&nbsp;په هغه ورځو کښې چې د سېلاب د راتلو نه اول وُو هغوئ خوړل، څښل، ودونه يې کول او ودونه يې ورکول، تر هغې ورځې پورې چې نوح په کشتۍ کښې ننوتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22877, 'Matthew 24:39', 'Matthew', 24, 39, '&nbsp;او دوئ تر هغې هيڅ خبر نۀ وُو ترڅو چې سېلاب رانۀ غلو او دوئ يې لاهو نۀ کړل. دغه شان به د اِبن آدم په راتلو هم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22878, 'Matthew 24:40', 'Matthew', 24, 40, '&nbsp;نو هغه وخت به دوه کسان په پټى کښې وى، يو به بوتلے شى او بل به پرېښودلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22879, 'Matthew 24:41', 'Matthew', 24, 41, '&nbsp;دوه ښځې به مېچن کوى، يوه به بوتلے شى او بله به پرېښودلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22880, 'Matthew 24:42', 'Matthew', 24, 42, '&nbsp;نو بيا تاسو بېدار اوسئ، ځکه چې تاسو په دې نۀ يئ خبر چې مالِک به په کومه ورځ راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22881, 'Matthew 24:43', 'Matthew', 24, 43, '&nbsp;خو ياد ساتئ، کۀ د کور مالِک خبر وے چې غل به د شپې په کوم وخت کښې راځى نو هغه به بېدار وے او خپل کور به يې کنډر کېدو ته پرېښے نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22882, 'Matthew 24:44', 'Matthew', 24, 44, '&nbsp;نو بيا تاسو هم تيار اوسئ ځکه چې اِبن آدم به په داسې وخت کښې راځى چې ستاسو به په خيال خاطر کښې هم نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22883, 'Matthew 24:45', 'Matthew', 24, 45, '&nbsp;نو بيا وفادار او خيال ساتونکے نوکر څوک دے؟ هغه څوک چا ته چې مالِک د کور اختيار ورکړے وى چې د کور د نورو نوکرانو خيال ساتى او هغوئ له مناسب خوراک ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
