(22885, 'Matthew 24:47', 'Matthew', 24, 47, '&nbsp;زۀ تاسو ته رښتيا وايم چې مالِک به دۀ له د خپل ټول مال واک اختيار ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22886, 'Matthew 24:48', 'Matthew', 24, 48, '&nbsp;خو کۀ هغه بد نوکر د خپل ځان سره داسې ووائى چې، بويه چې زما مالِک راځى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22887, 'Matthew 24:49', 'Matthew', 24, 49, '&nbsp;او بيا د نورو نوکرانو په وهلو لاس پورې کړى او په خوړلو او څښلو آخته وى او په نشه کښې وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22888, 'Matthew 24:50', 'Matthew', 24, 50, '&nbsp;نو مالِک به يې په داسې ورځ راشى چې د دۀ په خيال خاطر کښې به نۀ وى او په داسې وخت به راشى چې هغه به خبر هم نۀ وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22889, 'Matthew 24:51', 'Matthew', 24, 51, '&nbsp;نو هغه به يې په وهلو تک شين کړى او دغه شان به يې په مُنافقانو کښې شامل کړى. چرته چې به ژړا او د غاښونو چيچل وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22890, 'Matthew 25:1', 'Matthew', 25, 1, '&nbsp;”په هغه وخت به د آسمان بادشاهى د لسو پېغلو په شان وى چا چې مشعلونه واخستل چې د وادۀ د زلمى استقبال له وروځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22891, 'Matthew 25:2', 'Matthew', 25, 2, '&nbsp;پينځۀ کم عقلې وې او پينځۀ هوښيارې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
