(22893, 'Matthew 25:4', 'Matthew', 25, 4, '&nbsp;خو هغه هوښيارو د ځان سره د تېلو کوپۍ هم واخستلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22894, 'Matthew 25:5', 'Matthew', 25, 5, '&nbsp;کله چې د وادۀ زلمے په راتلو کښې ايسار شو نو هغوئ ټولو له خوب ورغلو او اودې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22895, 'Matthew 25:6', 'Matthew', 25, 6, '&nbsp;خو په نيمه شپه کښې چغې شوې، وګورئ د وادۀ زلمے راغلو. راشئ چې وې ګورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
